{
  "title": "The Mirror Rescue",
  "gate_token": "CMKiuwjpyjY4eRQ0odd-DQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuers gather at the ruined city gates.",
      "visual_description": "Cracked stone gates loom under a grey sky; broken royal banners hang limp; the team huddles near a shattered arch.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unfolds a crumbling map on a fallen pillar.",
      "visual_description": "Mara traces ink lines on aged parchment with her compass; the oracle lamp flickers nearby; the glass diver peers over her shoulder.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scampers ahead to scout the main avenue.",
      "visual_description": "Small metal fox weaves between cobblestones and debris; its blue eyes scan empty market stalls hung with tattered cloth.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol clanks past a side street.",
      "visual_description": "Sunlight glints off metal helms and pauldrons as the column marches; the team presses flat against a wall, holding breath.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The flame eye flares; its light casts writhing shadows on a crooked spire whose windows pulse with sickly green light.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "A frightened townsman gestures frantically from a doorway.",
      "visual_description": "A haggard figure in torn cloth points toward the tower and shakes his head; the team exchanges glances but continues.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver tests a window to see if it mirrors a shortcut.",
      "visual_description": "He presses his helmet against a fractured pane; reflections ripple and show a corridor inside the tower instead of the street.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The sleeping tax collector snores on a bench, papers stuck to his sleeve.",
      "visual_description": "He slumps over a ledger-book pillow, stamped tax forms fluttering; the team steps quietly around him.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara locates a hidden passage marked on her map.",
      "visual_description": "She traces a faint ink line behind a collapsed fountain; a narrow stairway descends into darkness.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox triggers a floor trap; a metal jaw snaps shut.",
      "visual_description": "The little fox leaps back as iron teeth clamp on stone; its tail winds furiously as it reorients.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver swims through a cracked mirror into a locked chamber.",
      "visual_description": "He emerges from the glass surface like a diver surfacing; the room is dusty with a single barred window high up.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara reads a riddle on a magic door; the oracle lamp illuminates symbols.",
      "visual_description": "Carved runes glow as the lamp's flame brightens; Mara mutters solutions under her breath.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Rumors of a dragon draw the team's attention to a distant roar.",
      "visual_description": "A deep rumble shakes the walls; a huge shadow passes overhead beyond the broken ceiling.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector wakes briefly, then dozes off again.",
      "visual_description": "He opens one eye, mutters 'taxes are overdue,' and returns to snoring with papers rustling.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The magic door swings open at last, revealing the captive.",
      "visual_description": "Runes fade; a dim hallway leads to a small cell where a figure waits, chained.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver uses a shard of mirror to cut the chains.",
      "visual_description": "He angles a reflective shard; light focuses, metal snaps; the rescued person stands free.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The team flees through crumbling corridors toward the escape bridge.",
      "visual_description": "Dust and rubble fall; the oracle lamp swings wildly; the tin fox leads the way, key-wind tail spinning.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the final bridge as the city collapses behind them.",
      "visual_description": "A stone bridge arches over a chasm; behind them towers crumble; ahead the road leads to open countryside under a clear sky.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

